def find_rects(g):
    rects=[]; H=len(g); W=len(g[0]); seen=set()
    for r in range(H):
        for c in range(W):
            if g[r][c] and (r,c) not in seen:
                col=g[r][c]
                # extents
                r2=r
                while r2+1<H and g[r2+1][c]==col: r2+=1
                c2=c
                while c2+1<W and g[r][c2+1]==col: c2+=1
                if r2-r>=2 and c2-c>=2:
                    ok=all(g[i][j]==col or (r<i<r2 and c<j<c2) for i in range(r,r2+1) for j in range(c,c2+1))
                    if ok and g[r2][c2]==col:
                        rects.append((r,c,r2,c2,col))
                        for i in range(r,r2+1):
                            for j in range(c,c2+1): seen.add((i,j))
    return rects

def f(g):
    H=len(g);W=len(g[0])
    rects=find_rects(g)
    from collections import Counter
    cnt=Counter()
    for r in range(H):
        for c in range(W):
            if g[r][c]:
                inside=any(a<=r<=b and cc<=c<=dd for a,b,cc,dd,_ in [(x[0],x[2],x[1],x[3]) for x in rects])
                if not inside: cnt[g[r][c]]+=1
    fill=cnt.most_common(1)[0][0] if cnt else 0
    out=[[0]*W for _ in range(H)]
    for a,b,cc,dd,col in rects:
        for i in range(a,b+1):
            for j in range(cc,dd+1):
                if i in(a,b) or j in(cc,dd): out[i][j]=col
                elif (i+j)%2==0: out[i][j]=fill
    return out

